\label{lem:weightflow2flowflow_Bob}
  If Bob has a winning strategy in the weight-flow game, 
  then for each single tree~$T$, Bob has a winning strategy in the flow-flow game with the same parameters $\gamma$ and~$s$.

\label{lem:weightflow2flowflow_Alice}
  If Alice has a winning strategy in the weight-flow game, 
  then Alice has a winning strategy in the flow-flow game with the same parameters and for the tree consisting of all strings with zeros in even positions.

\label{lem:getForests}
  Given $2^k-1$ leafless trees $T_1, \ldots, T_{2^k-1}$ that are jointly predicting, 
  one can compute $k$ forests $F_1, \ldots, F_k$ that are a good partition of these trees.

\label{lem:lowerbound_strategy}
  For each~$N$, Alice has a strategy in the weight-flow game in which for some $N$-bit string $z$ she achieves the following. 
  For infinitely many rounds,
  \begin{equation}\tag{$*$}\label{eq:winning}
    \sum_{n \le N} \frac {w(z_{\le n})} {B(z_{\le n})} \;>\;\Omega(\log N).
  \end{equation}
  Moreover, these strategies are computable given~$N$.
